function usablePrefixLen(indexCols, eqCols) {
  // indexCols: ordered list, e.g. ['a','b','c']
  // eqCols: Set of columns the query constrains by equality
  // returns how many LEADING columns the btree can seek on
  let used = 0;
  for (const col of indexCols) {
    if (eqCols.has(col)) used++;   // BUG: counts matches anywhere, not the contiguous prefix
  }
  return used;
}

